{
  "name": "双通道函数/任意波形发生器",
  "name_en": "Dual-Channel Function / Arbitrary Waveform Generator",
  "manufacturer": "Tektronix",
  "description": "一台台式双通道函数/任意波形信号发生器，用于在实验室中输出正弦波、方波等标准波形以及用户自定义波形，并调节频率、幅度、偏置和输出状态。它适合用于电子电路测试、传感器激励、触发实验以及需要双通道同步或频率锁定的信号源应用。",
  "description_en": "A benchtop dual-channel function/arbitrary waveform generator used in laboratories to produce standard waveforms such as sine and square waves as well as user-defined waveforms, with control over frequency, amplitude, offset, and output state. It is suitable for electronics testing, sensor excitation, trigger-based experiments, and signal-source tasks requiring two-channel synchronisation or frequency locking.",
  "tag_hints": [
    "function generator",
    "arbitrary waveform generation",
    "dual-channel signal source",
    "frequency lock",
    "waveform synchronization",
    "software trigger",
    "benchtop test instrument"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "连接仪器",
      "description_en": "Connect to the instrument"
    },
    {
      "action_name": "auto-close",
      "description": "断开与仪器的连接",
      "description_en": "Disconnect from the instrument"
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置通信超时时间",
      "description_en": "Get/set the communication timeout"
    },
    {
      "action_name": "auto-write",
      "description": "向仪器发送命令",
      "description_en": "Send a command to the instrument"
    },
    {
      "action_name": "auto-query",
      "description": "查询仪器",
      "description_en": "Query the instrument"
    },
    {
      "action_name": "auto-print_settings",
      "description": "显示两个通道的当前设置",
      "description_en": "Display the current settings of both channels"
    },
    {
      "action_name": "auto-set_settings",
      "description": "设置两个通道的参数",
      "description_en": "Set the settings of both channels"
    },
    {
      "action_name": "auto-syncronise_waveforms",
      "description": "同步两个通道的波形",
      "description_en": "Synchronise the waveforms of the two channels"
    },
    {
      "action_name": "auto-set_frequency_lock",
      "description": "设置通道间频率锁定状态",
      "description_en": "Set the frequency lock state between channels"
    },
    {
      "action_name": "auto-software_trig",
      "description": "发送软件触发",
      "description_en": "Send a software trigger"
    },
    {
      "action_name": "auto-set_custom_waveform",
      "description": "定义自定义波形",
      "description_en": "Define a custom waveform"
    },
    {
      "action_name": "auto-get_error",
      "description": "获取错误/事件队列内容",
      "description_en": "Get the contents of the error/event queue"
    },
    {
      "action_name": "auto-get_settings",
      "description": "获取两个通道的当前设置",
      "description_en": "Get the current settings of both channels"
    },
    {
      "action_name": "auto-get_frequency_lock",
      "description": "获取通道间频率锁定状态",
      "description_en": "Get the frequency lock state between channels"
    },
    {
      "action_name": "auto-get_waveform_catalogue",
      "description": "获取已存储自定义波形目录",
      "description_en": "Get the catalogue of stored custom waveforms"
    },
    {
      "action_name": "auto-get_custom_waveform",
      "description": "获取自定义波形",
      "description_en": "Get a custom waveform"
    },
    {
      "action_name": "auto-set_stricter_limits",
      "description": "定义更严格的软件限制",
      "description_en": "Define stricter software limits"
    },
    {
      "action_name": "auto-set_limit",
      "description": "定义参数限制",
      "description_en": "Define a parameter limit"
    },
    {
      "action_name": "auto-get_output_state",
      "description": "获取输出状态",
      "description_en": "Get the output state"
    },
    {
      "action_name": "auto-get_function",
      "description": "获取波形函数",
      "description_en": "Get the waveform function"
    },
    {
      "action_name": "auto-get_amplitude",
      "description": "获取输出幅度",
      "description_en": "Get the output amplitude"
    },
    {
      "action_name": "auto-get_offset",
      "description": "获取输出偏置",
      "description_en": "Get the output offset"
    },
    {
      "action_name": "auto-get_frequency",
      "description": "获取输出频率",
      "description_en": "Get the output frequency"
    },
    {
      "action_name": "auto-get_frequency_lims",
      "description": "获取频率限制",
      "description_en": "Get the frequency limits"
    },
    {
      "action_name": "auto-get_voltage_lims",
      "description": "获取电压限制",
      "description_en": "Get the voltage limits"
    },
    {
      "action_name": "auto-get_amplitude_lims",
      "description": "获取幅度限制",
      "description_en": "Get the amplitude limits"
    },
    {
      "action_name": "auto-set_output_state",
      "description": "设置输出状态",
      "description_en": "Set the output state"
    },
    {
      "action_name": "auto-get_output",
      "description": "获取输出配置",
      "description_en": "Get the output configuration"
    },
    {
      "action_name": "auto-set_output",
      "description": "设置输出配置",
      "description_en": "Set the output configuration"
    },
    {
      "action_name": "auto-set_function",
      "description": "设置波形函数",
      "description_en": "Set the waveform function"
    },
    {
      "action_name": "auto-set_amplitude",
      "description": "设置输出幅度",
      "description_en": "Set the output amplitude"
    },
    {
      "action_name": "auto-set_offset",
      "description": "设置输出偏置",
      "description_en": "Set the output offset"
    },
    {
      "action_name": "auto-set_frequency",
      "description": "设置输出频率",
      "description_en": "Set the output frequency"
    }
  ]
}

